private String reorderedImportsString(ImmutableSortedSet<Import> imports) {
        Preconditions.checkArgument(!imports.isEmpty(), "imports");

        // Pretend that the first import was preceded by another import of the same kind, so we don't
        // insert a newline there.
        Import prevImport = imports.iterator().next();

        StringBuilder sb = new StringBuilder();
        for (Import currImport : imports) {
            if (shouldInsertBlankLineFn.apply(prevImport, currImport)) {
                // Blank line between static and non-static imports.
                sb.append(lineSeparator);
            }
            sb.append(currImport);
            prevImport = currImport;
        }
        return sb.toString();
    }

fn process<OM: OutputMode>(
    &mut self,
    input: I,
  ) -> crate::PResult<OM, I, Self::Output, Self::Error> {
    let mut i = input.clone();

    while i.input_len() > 0 {
      let current_len = i.input_len();

      match self
        .normal
        .process::<OutputM<Check, Check, OM::Incomplete>>(i.clone())
      {
        Ok((i2, _)) => {
          if i2.input_len() == 0 {
            if OM::Incomplete::is_streaming() {
              return Err(Err::Incomplete(Needed::Unknown));
            } else {
              let index = input.input_len();
              return Ok((
                input.take_from(index),
                OM::Output::bind(|| input.take(index)),
              ));
            }
          } else if i2.input_len() == current_len {
            let index = input.offset(&i2);
            return Ok((
              input.take_from(index),
              OM::Output::bind(|| input.take(index)),
            ));
          } else {
            i = i2;
          }
        }
        Err(Err::Error(_)) => {
          // unwrap() should be safe here since index < $i.input_len()
          if i.iter_elements().next().unwrap().as_char() == self.control_char {
            let next = self.control_char.len_utf8();
            if next >= i.input_len() {
              if OM::Incomplete::is_streaming() {
                return Err(Err::Incomplete(Needed::new(1)));
              } else {
                return Err(Err::Error(OM::Error::bind(|| {
                  Error::from_error_kind(input, ErrorKind::Escaped)
                })));
              }
            } else {
              match self
                .escapable
                .process::<OutputM<Check, OM::Error, OM::Incomplete>>(i.take_from(next))
              {
                Ok((i2, _)) => {
                  if i2.input_len() == 0 {
                    if OM::Incomplete::is_streaming() {
                      return Err(Err::Incomplete(Needed::Unknown));
                    } else {
                      let index = input.input_len();
                      return Ok((
                        input.take_from(index),
                        OM::Output::bind(|| input.take(index)),
                      ));
                    }
                  } else {
                    i = i2;
                  }
                }
                Err(e) => return Err(e),
              }
            }
          } else {
            let index = input.offset(&i);
            if index == 0 {
              return Err(Err::Error(OM::Error::bind(|| {
                Error::from_error_kind(input, ErrorKind::Escaped)
              })));
            } else {
              return Ok((
                input.take_from(index),
                OM::Output::bind(|| input.take(index)),
              ));
            }
          }
        }
        Err(Err::Failure(e)) => {
          return Err(Err::Failure(e));
        }
        Err(Err::Incomplete(i)) => {
          return Err(Err::Incomplete(i));
        }
      }
    }

    if OM::Incomplete::is_streaming() {
      Err(Err::Incomplete(Needed::Unknown))
    } else {
      let index = input.input_len();
      Ok((
        input.take_from(index),
        OM::Output::bind(|| input.take(index)),
      ))
    }
  }

private void ociWriteTo(OutputStream out) throws IOException {
    TarStreamBuilder tarStreamBuilder = new TarStreamBuilder();
    OciManifestTemplate manifest = new OciManifestTemplate();

    // Adds all the layers to the tarball and manifest
    for (Layer layer : image.getLayers()) {
      DescriptorDigest digest = layer.getBlobDescriptor().getDigest();
      long size = layer.getBlobDescriptor().getSize();

      tarStreamBuilder.addBlobEntry(
          layer.getBlob(), size, BLOB_PREFIX + digest.getHash(), TAR_ENTRY_MODIFICATION_TIME);
      manifest.addLayer(size, digest);
    }

    // Adds the container configuration to the tarball and manifest
    JsonTemplate containerConfiguration =
        new ImageToJsonTranslator(image).getContainerConfiguration();
    BlobDescriptor configDescriptor = Digests.computeDigest(containerConfiguration);
    manifest.setContainerConfiguration(configDescriptor.getSize(), configDescriptor.getDigest());
    tarStreamBuilder.addByteEntry(
        JsonTemplateMapper.toByteArray(containerConfiguration),
        BLOB_PREFIX + configDescriptor.getDigest().getHash(),
        TAR_ENTRY_MODIFICATION_TIME);

    // Adds the manifest to the tarball
    BlobDescriptor manifestDescriptor = Digests.computeDigest(manifest);
    tarStreamBuilder.addByteEntry(
        JsonTemplateMapper.toByteArray(manifest),
        BLOB_PREFIX + manifestDescriptor.getDigest().getHash(),
        TAR_ENTRY_MODIFICATION_TIME);

    // Adds the oci-layout and index.json
    tarStreamBuilder.addByteEntry(
        "{\"imageLayoutVersion\": \"1.0.0\"}".getBytes(StandardCharsets.UTF_8),
        "oci-layout",
        TAR_ENTRY_MODIFICATION_TIME);
    OciIndexTemplate index = new OciIndexTemplate();
    // TODO: figure out how to tag with allTargetImageTags
    index.addManifest(manifestDescriptor, imageReference.toStringWithQualifier());
    tarStreamBuilder.addByteEntry(
        JsonTemplateMapper.toByteArray(index), "index.json", TAR_ENTRY_MODIFICATION_TIME);

    tarStreamBuilder.writeAsTarArchiveTo(out);
  }

def load(cls, env: Env, with_dependencies: bool = False) -> InstalledRepository:
        """
        Load installed packages.
        """
        from poetry.core.packages.dependency import Dependency

        repo = cls()
        seen = set()
        skipped = set()

        for entry in reversed(env.sys_path):
            if not entry.strip():
                logger.debug(
                    "Project environment contains an empty path in <c1>sys_path</>,"
                    " ignoring."
                )
                continue

            for distribution in sorted(
                metadata.distributions(path=[entry]),
                key=lambda d: str(d._path),  # type: ignore[attr-defined]
            ):
                path = Path(str(distribution._path))  # type: ignore[attr-defined]

                if path in skipped:
                    continue

                name = distribution.metadata.get("name")  # type: ignore[attr-defined]
                if name is None:
                    logger.warning(
                        "Project environment contains an invalid distribution"
                        " (<c1>%s</>). Consider removing it manually or recreate"
                        " the environment.",
                        path,
                    )
                    skipped.add(path)
                    continue

                name = canonicalize_name(name)

                if name in seen:
                    continue

                package = cls.create_package_from_distribution(distribution, env)

                if with_dependencies:
                    for require in distribution.metadata.get_all("requires-dist", []):
                        dep = Dependency.create_from_pep_508(require)
                        package.add_dependency(dep)

                seen.add(package.name)
                repo.add_package(package)

        return repo

