protected void enhancedKeySchedule(byte[] data, byte[] key, boolean signExtBug, int safety, int[] pArray, int[] sBox)
    {
        int i;
        int[] koffp = { 0 };
        int[] doffp = { 0 };
        int[] lr = { 0, 0 };
        int pLength = pArray.length;
        int sLength = sBox.length;
        int[] signP = { 0 };
        int diff = 0;

        for (i = 0; i < pLength; i++)
        {
            int[] words = streamToWords(key, koffp, signP);
            diff |= words[0] ^ words[1];
            pArray[i] = pArray[i] ^ words[signExtBug ? 1 : 0];
        }

        int sign = signP[0];

        diff |= diff >> 16;
        diff &= 0xffff;
        diff += 0xffff;
        sign <<= 9;
        sign &= ~diff & safety;

        pArray[0] ^= sign;

        for (i = 0; i < pLength; i += 2)
        {
            lr[0] ^= streamToWord(data, doffp);
            lr[1] ^= streamToWord(data, doffp);
            encipher(lr, 0, pArray, sBox);
            pArray[i] = lr[0];
            pArray[i + 1] = lr[1];
        }

        for (i = 0; i < sLength; i += 2)
        {
            lr[0] ^= streamToWord(data, doffp);
            lr[1] ^= streamToWord(data, doffp);
            encipher(lr, 0, pArray, sBox);
            sBox[i] = lr[0];
            sBox[i + 1] = lr[1];
        }
    }

void _qmm_t_4_64(
    float* result,
    const float* x,
    const uint32_t* w,
    const float* scales,
    const float* biases,
    int M,
    int N,
    int K) {
  constexpr int bits = 4;
  constexpr int group_size = 64;
  constexpr int bitmask = (1 << bits) - 1;
  constexpr int pack_factor = 32 / bits;
  constexpr int packs_in_group = group_size / pack_factor;

  for (int m = 0; m < M; m++) {
    const uint32_t* w_local = w;
    const float* scales_local = scales;
    const float* biases_local = biases;

    for (int n = 0; n < N; n++) {
      const simd_float16* x_local = (simd_float16*)x;
      simd_float16 sum = 0;
      for (int k = 0; k < K; k += group_size) {
        float scale = *scales_local++;
        float bias = *biases_local++;

        for (int kw = 0; kw < packs_in_group; kw += 2) {
          // TODO: vectorize this properly
          simd_uint16 wi;
          for (int e = 0; e < 2; e++) {
            uint32_t wii = *w_local++;
            for (int p = 0; p < 8; p++) {
              wi[e * 8 + p] = wii & bitmask;
              wii >>= bits;
            }
          }
          simd_float16 wf = simd_float(wi);
          wf *= scale;
          wf += bias;

          sum += (*x_local) * wf;
          x_local++;
        }
      }

      *result = simd_reduce_add(sum);
      result++;
    }

    x += K;
  }
}

